mapper.update:
UPDATE zw_student
USER_ID = #{userId}, SEX = #{sex}, STUDENT_CODE = #{studentCode}, EMAIL = #{email}, STUDENT_STATUS = #{studentStatus}, STUDENT_TYPE = #{studentType}, PHONE = #{phone}, GRA = #{gra}, CLA = #{cla},
WHERE STUDENT_ID = #{studentId}

mapper.select:
SELECT s.*, u.USER_NAME, u.NAME, sex.CODE_DESC as SEX_DESC, ss.CODE_DESC as STUDENT_STATUS_DESC, st.CODE_DESC as STUDENT_TYPE_DESC FROM zw_student s LEFT JOIN g_user u ON s.USER_ID = u.USER_ID LEFT JOIN g_code sex ON s.SEX = sex.CODE_ID LEFT JOIN g_code ss ON s.STUDENT_STATUS = ss.CODE_ID LEFT JOIN g_code st ON s.STUDENT_TYPE = st.CODE_ID
AND s.GRA = #{gra}
AND s.CLA = #{cla}
AND s.STUDENT_TYPE = #{studentType}
AND u.NAME LIKE CONCAT('%', #{name}, '%')
ORDER BY u.USER_NAME

mapper.update:
UPDATE g_user
USER_NAME = #{userName}, NAME = #{name}, PASSWORD = #{password},
WHERE USER_ID = #{userId}
